def closest_integer(value):
    from math import floor, ceil

    num = float(value)
    if num == int(num):
        return int(num)

    lower = floor(num)
    upper = ceil(num)
    diff_lower = abs(num - lower)
    diff_upper = abs(num - upper)

    if diff_lower < diff_upper:
        return lower
    elif diff_upper < diff_lower:
        return upper
    else:
        # Equidistant, round away from zero
        if num > 0:
            return upper
        else:
            return lower
