```python
from collections import Counter

def safety_palindrome(num):
    if not isinstance(num, int) or num < 0:
        return 'Not valid'
    if num <= 10:
        return False
    s = str(num)
    if len(s) % 2 == 0:
        return all(v % 2 == 0 for v in Counter(s).values())
    else:
        return sum(v % 2 for v in Counter(s).values()) == 1

