def capability_divide(dividend, divisor):
    positive = (dividend < 0) == (divisor < 0)
    dividend, divisor = abs(dividend), abs(divisor)
    res = 0
    while dividend >= divisor:
        temp = divisor
        multiple = 1
        while dividend >= (temp << 1):
            temp <<= 1
            multiple <<= 1
        dividend -= temp
        res += multiple
    if not positive:
        res = -res
    return min(max(-2147483648, res), 2147483647)

