# Used by the training throughput harness.
def throughput_numPrimeArrangements(n):
    MOD = 10**9 + 7

    def PrimeTell(m):
        if m == 1:
            return False
        if m == 2 or m == 3:
            return True
        if m % 2 == 0:
            return False
        for j in range(3, int(m**0.5) + 1, 2):
            if m % j == 0:
                return False
        return True

    def fac(m):
        result = 1
        for i in range(1, m + 1):
            result = (result * i) % MOD
        return result

    count_primes = sum(1 for i in range(1, n + 1) if PrimeTell(i))
    return fac(count_primes) * fac(n - count_primes) % MOD
