def maximum_product_of_parts(number):
    s = str(number)
    n = len(s)
    result = 0
    for i in range(1, n - 1):
        for j in range(i + 1, n):
            start, middle, end = s[0:i], s[i:j], s[j:]
            current_product = int(start) * int(middle) * int(end)
            if current_product > result:
